import type { PageLoad } from './$types';
import { parseYearParam } from '$lib/utils/spendingYear';

/**
 * The Spending report's selected year lives in the URL (`/spending?year=2025`).
 *
 * Reading it in `load` (rather than a client-side `$derived` off the page store)
 * is what makes it reliable: SvelteKit re-runs `load` with the correct `url` on
 * every navigation — the year arrows (`goto`), a browser Back from a drill-down,
 * and a full refresh — so `data.year` is always in lock-step with `?year=`.
 * Earlier client-only attempts (read-once in onMount, then `$derived` off the
 * `$app/stores` / `$app/state` page) went stale on Back.
 */
export const load: PageLoad = ({ url }) => {
	return { year: parseYearParam(url.searchParams, new Date().getFullYear()) };
};
