/**
 * The Spending report's selected year is persisted in the URL
 * (`/spending?year=2025`) so it survives a refresh and navigating away and back.
 * This is the pure parse of that `year` query param, with a fallback for a
 * missing/garbage/out-of-range value.
 */

/** Lowest / highest year we'll accept from the URL, to reject absurd values. */
const MIN_YEAR = 1900;
const MAX_YEAR = 2999;

/**
 * Read a plausible calendar year from a URL's search params.
 *
 * @param params - the page's `URLSearchParams` (reads the `year` key)
 * @param fallbackYear - year to use when `year` is absent, non-numeric, or
 *   outside [1900, 2999] (callers pass the current year)
 */
export function parseYearParam(params: URLSearchParams, fallbackYear: number): number {
	const raw = params.get('year');
	const parsed = raw ? Number.parseInt(raw, 10) : NaN;
	if (Number.isInteger(parsed) && parsed >= MIN_YEAR && parsed <= MAX_YEAR) {
		return parsed;
	}
	return fallbackYear;
}
