/**
 * ExpenseService
 *
 * Service for managing expenses derived from receipts
 * Specification: #{#exp1b} - Expenses Derived from Receipts
 * Authority: system
 * Priority: Critical
 *
 * Key Principles:
 * - Expenses are computed views, not separate database entities
 * - Each receipt generates exactly one expense (1:1 mapping)
 * - Deleting a receipt automatically removes the expense (CASCADE)
 * - Creating a receipt automatically makes it available as an expense
 */

import type { SupabaseClient } from '@supabase/supabase-js';

/**
 * Expense data structure derived from receipts
 * #{#umf1b} - Extended with matched_transaction_id for unmatched filter
 */
export interface Expense {
	receipt_id: string;
	merchant_name: string;
	total_amount: number | null; // null when OCR could not read the receipt amount
	transaction_date: string;
	receipt_image_path?: string;
	category_id: string | null;
	categorization_source: 'manual' | 'auto' | null;
	category_name?: string | null;
	category_color?: string | null;
	matched_transaction_id: string | null; // #{#umf1b} - Match status for reconciliation
	currency: string | null; // #{#fcr4a} - Original currency for display
	exchange_rate_to_cad: number | null; // #{#fcr4a} - Bank of Canada rate for estimated CAD
	notes: string | null; // Free-text Note, carried for the row preview only
}

/**
 * The least a row must carry to be matched against a vendor rule: which receipt
 * it is, which merchant it names, and whether it already has a category.
 *
 * `Expense` satisfies this, and so does the Receipts page — which holds
 * `ReceiptRow[]` plus a separate category map rather than `Expense[]`. The rule
 * methods take this instead of a full `Expense` so both list pages can drive the
 * same code, rather than one of them assembling a throwaway `Expense`.
 */
export interface VendorRuleCandidate {
	receipt_id: string;
	merchant_name: string;
	category_id: string | null;
}

/**
 * Filter options for querying expenses
 */
export interface ExpenseFilters {
	startDate?: string;
	endDate?: string;
	categoryId?: string;
	merchantName?: string;
}

/**
 * Shape of a receipts row as returned by the expense query, including the
 * embedded expense_categories -> categories join (1:1 per receipt).
 */
interface ExpenseReceiptRow {
	id: string;
	merchant_name: string;
	total_amount: number | null; // receipts.total_amount is nullable (OCR may fail)
	transaction_date: string;
	receipt_image_path?: string;
	matched_transaction_id: string | null;
	currency: string | null;
	exchange_rate_to_cad: number | null;
	notes: string | null;
	expense_categories: {
		category_id: string | null;
		categorization_source: 'manual' | 'auto' | null;
		categories: {
			name: string | null;
			color: string | null;
		} | null;
	} | null;
}

/**
 * Re-shapes a PostgREST embedded-join result to its real runtime shape.
 *
 * The untyped client infers to-one embeds (`expense_categories`, `categories`) as
 * arrays, but a 1:1 relationship returns a single object (or null) at runtime. This
 * names the single boundary where we bridge the inferred type to the runtime shape,
 * so the coercion isn't re-asserted with an `as unknown as` at each call site.
 */
function coerceEmbed<T>(value: unknown): T {
	return value as T;
}

/**
 * ExpenseService Class
 * Handles all expense-related operations
 */
export class ExpenseService {
	private supabase: SupabaseClient;

	constructor(supabase: SupabaseClient) {
		this.supabase = supabase;
	}

	/**
	 * Get expenses for a user (derived from receipts)
	 *
	 * @param userId - User ID to filter expenses
	 * @param filters - Optional filters (date range, category, merchant)
	 * @returns Array of expenses
	 *
	 * Specification: #{#exp1b} Requirements 1, 2, 3, 7
	 */
	async getExpenses(userId: string, filters?: ExpenseFilters): Promise<Expense[]> {
		// Requirement: User ID validation
		if (!userId) {
			throw new Error('User ID is required');
		}

		const rows = await this.fetchAllReceiptRows(filters);
		const expenses = rows.map((receipt) => this.mapReceiptRowToExpense(receipt));

		return this.applyCategoryFilter(expenses, filters);
	}

	/**
	 * Fetch every receipt row matching the filters, paging past PostgREST's
	 * per-request row cap (1000 by default).
	 *
	 * Without paging, a family with more than 1000 receipts only ever sees the
	 * newest 1000: the Spending-report drill-down into an older year lands on an
	 * empty Expenses list ("hiding all 1000 expenses"), and the report itself
	 * undercounts any year that exceeds the cap. This became reachable once the
	 * historical-expense importer could add thousands of receipts at once.
	 */
	private async fetchAllReceiptRows(filters?: ExpenseFilters): Promise<ExpenseReceiptRow[]> {
		const PAGE_SIZE = 1000;
		const all: ExpenseReceiptRow[] = [];

		for (let from = 0; ; from += PAGE_SIZE) {
			const { data, error } = await this.buildExpenseQuery(filters).range(
				from,
				from + PAGE_SIZE - 1
			);
			if (error) {
				throw new Error(error.message);
			}

			const batch = coerceEmbed<ExpenseReceiptRow[]>(data ?? []);
			all.push(...batch);

			// A short page means we've reached the end.
			if (batch.length < PAGE_SIZE) break;
		}

		return all;
	}

	/**
	 * Build the receipts query that computes the expense view: receipts joined
	 * with expense_categories and categories, with SQL-level filters and the
	 * default sort applied.
	 *
	 * #{#umf1b} - Includes matched_transaction_id to support the unmatched filter.
	 * Don't filter by user_id - let RLS policies handle access based on family membership.
	 */
	private buildExpenseQuery(filters?: ExpenseFilters) {
		let query = this.supabase.from('receipts').select(
			`
				id,
				merchant_name,
				total_amount,
				transaction_date,
				receipt_image_path,
				matched_transaction_id,
				currency,
				exchange_rate_to_cad,
				notes,
				expense_categories (
					category_id,
					categorization_source,
					categories (
						name,
						color
					)
				)
			`
		);

		if (filters?.startDate) {
			query = query.gte('transaction_date', filters.startDate);
		}

		if (filters?.endDate) {
			query = query.lte('transaction_date', filters.endDate);

