import { describe, it, expect } from 'vitest';
import {
	MAX_PERIOD_MONTHS,
	addMonths,
	compareYearMonth,
	defaultPeriod,
	formatPeriod,
	formatYearMonth,
	monthColumnLabels,
	parsePeriodParams,
	parseYearMonth,
	periodLength,
	periodParams,
	shiftPeriod,
	type Period
} from './spendingPeriod';

const params = (query: string) => new URLSearchParams(query);
const AUG_2026 = { year: 2026, month: 8 };

describe('parseYearMonth', () => {
	it('parses a canonical YYYY-MM', () => {
		expect(parseYearMonth('2025-07')).toEqual({ year: 2025, month: 7 });
	});

	it('rejects null, junk, and the wrong shape', () => {
		expect(parseYearMonth(null)).toBeNull();
		expect(parseYearMonth('')).toBeNull();
		expect(parseYearMonth('2025')).toBeNull();
		expect(parseYearMonth('2025-7')).toBeNull();
		expect(parseYearMonth('2025-07-01')).toBeNull();
		expect(parseYearMonth('abcd-ef')).toBeNull();
	});

	it('rejects an impossible month or an absurd year', () => {
		expect(parseYearMonth('2025-00')).toBeNull();
		expect(parseYearMonth('2025-13')).toBeNull();
		expect(parseYearMonth('1899-01')).toBeNull();
		expect(parseYearMonth('3000-01')).toBeNull();
	});
});

describe('formatYearMonth', () => {
	it('zero-pads the month', () => {
		expect(formatYearMonth({ year: 2026, month: 3 })).toBe('2026-03');
		expect(formatYearMonth({ year: 2026, month: 12 })).toBe('2026-12');
	});
});

describe('addMonths / compareYearMonth', () => {
	it('rolls forward over a year boundary', () => {
		expect(addMonths({ year: 2025, month: 11 }, 3)).toEqual({ year: 2026, month: 2 });
	});

	it('rolls backward over a year boundary', () => {
		expect(addMonths({ year: 2026, month: 2 }, -3)).toEqual({ year: 2025, month: 11 });
	});

	it('shifts a whole year', () => {
		expect(addMonths({ year: 2026, month: 7 }, -12)).toEqual({ year: 2025, month: 7 });
	});

	it('orders by year then month', () => {
		expect(compareYearMonth({ year: 2025, month: 12 }, { year: 2026, month: 1 })).toBeLessThan(0);
		expect(compareYearMonth({ year: 2026, month: 3 }, { year: 2026, month: 3 })).toBe(0);
		expect(compareYearMonth({ year: 2026, month: 4 }, { year: 2026, month: 3 })).toBeGreaterThan(0);
	});
});

describe('periodLength / shiftPeriod', () => {
	it('counts both endpoints', () => {
		expect(periodLength({ from: { year: 2026, month: 1 }, to: { year: 2026, month: 1 } })).toBe(1);
		expect(periodLength({ from: { year: 2026, month: 1 }, to: { year: 2026, month: 12 } })).toBe(12);
		expect(periodLength({ from: { year: 2025, month: 7 }, to: { year: 2026, month: 6 } })).toBe(12);
	});

	it('shifts both endpoints together', () => {
		const period: Period = { from: { year: 2025, month: 7 }, to: { year: 2026, month: 6 } };
		expect(shiftPeriod(period, -12)).toEqual({
			from: { year: 2024, month: 7 },
			to: { year: 2025, month: 6 }
		});
	});
});

describe('defaultPeriod', () => {
	it('is the calendar year containing today', () => {
		expect(defaultPeriod(AUG_2026)).toEqual({
			from: { year: 2026, month: 1 },
			to: { year: 2026, month: 12 }
		});
	});
});

describe('parsePeriodParams', () => {
	it('reads a valid from/to pair', () => {
		expect(parsePeriodParams(params('from=2025-07&to=2026-06'), AUG_2026)).toEqual({
			from: { year: 2025, month: 7 },
			to: { year: 2026, month: 6 }
		});
	});

	it('accepts a single-month period', () => {
		expect(parsePeriodParams(params('from=2026-03&to=2026-03'), AUG_2026)).toEqual({
			from: { year: 2026, month: 3 },
			to: { year: 2026, month: 3 }
		});
	});

	it('falls back to the default when both params are absent', () => {
		expect(parsePeriodParams(params(''), AUG_2026)).toEqual(defaultPeriod(AUG_2026));
	});

	it('falls back when only one half is present', () => {
		expect(parsePeriodParams(params('from=2025-07'), AUG_2026)).toEqual(defaultPeriod(AUG_2026));
		expect(parsePeriodParams(params('to=2026-06'), AUG_2026)).toEqual(defaultPeriod(AUG_2026));
	});

	it('falls back when either half is unparseable', () => {
		expect(parsePeriodParams(params('from=nope&to=2026-06'), AUG_2026)).toEqual(
			defaultPeriod(AUG_2026)
		);
		expect(parsePeriodParams(params('from=2025-07&to=2026-99'), AUG_2026)).toEqual(
			defaultPeriod(AUG_2026)
		);
	});

	it('falls back when the range is inverted rather than swapping it', () => {
		expect(parsePeriodParams(params('from=2026-06&to=2025-07'), AUG_2026)).toEqual(
			defaultPeriod(AUG_2026)
		);
	});

	it('clamps an over-long range to 12 months, keeping the start', () => {
		expect(parsePeriodParams(params('from=2025-01&to=2026-06'), AUG_2026)).toEqual({
			from: { year: 2025, month: 1 },
			to: { year: 2025, month: 12 }
		});
	});

	it('translates the legacy ?year= param to that whole calendar year', () => {
		expect(parsePeriodParams(params('year=2025'), AUG_2026)).toEqual({
			from: { year: 2025, month: 1 },
			to: { year: 2025, month: 12 }
		});
	});

	it('prefers from/to over a legacy year when both are present', () => {
		expect(parsePeriodParams(params('year=2025&from=2024-03&to=2024-05'), AUG_2026)).toEqual({
			from: { year: 2024, month: 3 },
			to: { year: 2024, month: 5 }
		});
	});

	it('falls back for an absurd legacy year', () => {
		expect(parsePeriodParams(params('year=99999'), AUG_2026)).toEqual(defaultPeriod(AUG_2026));
	});

	it('is idempotent — its own serialization re-parses unchanged', () => {
		const cases = ['from=2025-07&to=2026-06', 'from=2025-01&to=2026-06', 'year=2025', ''];
		for (const query of cases) {
			const period = parsePeriodParams(params(query), AUG_2026);
			expect(parsePeriodParams(periodParams(period), AUG_2026)).toEqual(period);
		}
	});

	it('never returns a period longer than the cap', () => {
		const period = parsePeriodParams(params('from=1900-01&to=2999-12'), AUG_2026);
		expect(periodLength(period)).toBe(MAX_PERIOD_MONTHS);
	});
});

describe('periodParams', () => {
	it('serializes to the canonical from/to pair', () => {
		const period: Period = { from: { year: 2025, month: 7 }, to: { year: 2026, month: 6 } };
		expect(periodParams(period).toString()).toBe('from=2025-07&to=2026-06');
	});
});

describe('monthColumnLabels', () => {
	it('leaves months unqualified within a single calendar year', () => {
		const months = [
			{ year: 2026, month: 1 },
			{ year: 2026, month: 2 },
			{ year: 2026, month: 3 }
		];
		expect(monthColumnLabels(months)).toEqual(['Jan', 'Feb', 'Mar']);
	});

	it('year-qualifies once the months span two calendar years', () => {
		const months = [
			{ year: 2025, month: 11 },
			{ year: 2025, month: 12 },
			{ year: 2026, month: 1 }
		];
		expect(monthColumnLabels(months)).toEqual(['Nov 25', 'Dec 25', 'Jan 26']);
	});

	it('handles an empty list', () => {
		expect(monthColumnLabels([])).toEqual([]);
	});
});

describe('formatPeriod', () => {
	it('names a whole calendar year by its year alone', () => {
		expect(formatPeriod({ from: { year: 2026, month: 1 }, to: { year: 2026, month: 12 } })).toBe(
			'2026'
		);
	});

	it('names a part-year with its month range', () => {
		expect(formatPeriod({ from: { year: 2026, month: 1 }, to: { year: 2026, month: 8 } })).toBe(
			'Jan–Aug 2026'
		);
	});

	it('names a single month', () => {
		expect(formatPeriod({ from: { year: 2026, month: 3 }, to: { year: 2026, month: 3 } })).toBe(
			'Mar 2026'
		);
	});

	it('names a cross-year period with both years', () => {
		expect(formatPeriod({ from: { year: 2025, month: 7 }, to: { year: 2026, month: 6 } })).toBe(
			'Jul 2025 – Jun 2026'
		);
	});
});

