/**
 * Spending Report period (pure)
 *
 * The report used to be locked to one calendar year (`?year=`). It now runs over
 * a **selectable period of whole months, up to twelve** — e.g. Jul 2025 → Jun
 * 2026 — carried in the URL as `?from=2025-07&to=2026-06` and parsed in the
 * page's `load`, which stays the single source of truth for it.
 *
 * Design: docs/plans/2026-07-09-spending-report-design.md ("Period selection").
 *
 * No I/O and no clock: callers pass "today" in, the way `parseYearParam` used to
 * take a fallback year, so every rule here is unit-testable.
 */

/** A whole month. `month` is 1-based (1 = January). */
export interface YearMonth {
	year: number;
	month: number;
}

/** An inclusive run of whole months. `from` ≤ `to`, at most `MAX_PERIOD_MONTHS`. */
export interface Period {
	from: YearMonth;
	to: YearMonth;
}

/**
 * A period may span at most a year. "July → July" therefore means Jul 2025 →
 * Jun 2026: a 13th column would double-count July and make the year-over-year
 * comparison overlap its own first month.
 */
export const MAX_PERIOD_MONTHS = 12;

/** Lowest / highest year we'll accept from the URL, to reject absurd values. */
const MIN_YEAR = 1900;
const MAX_YEAR = 2999;

export const MONTH_LABELS = [
	'Jan',
	'Feb',
	'Mar',
	'Apr',
	'May',
	'Jun',
	'Jul',
	'Aug',
	'Sep',
	'Oct',
	'Nov',
	'Dec'
];

const YEAR_MONTH_PATTERN = /^(\d{4})-(\d{2})$/;

/** Canonical `YYYY-MM`. */
export function formatYearMonth(ym: YearMonth): string {
	return `${ym.year}-${String(ym.month).padStart(2, '0')}`;
}

/** Parse a canonical `YYYY-MM`; null for anything else (junk, out of range). */
export function parseYearMonth(raw: string | null): YearMonth | null {
	const match = raw ? YEAR_MONTH_PATTERN.exec(raw) : null;
	if (!match) return null;
	const year = Number(match[1]);
	const month = Number(match[2]);
	if (year < MIN_YEAR || year > MAX_YEAR || month < 1 || month > 12) return null;
	return { year, month };
}

/** Total months since year 0, so months can be compared and shifted as integers. */
function ordinal(ym: YearMonth): number {
	return ym.year * 12 + (ym.month - 1);
}

function fromOrdinal(value: number): YearMonth {
	return { year: Math.floor(value / 12), month: (value % 12) + 1 };
}

/** Shift a month by `months` (negative goes back), rolling over year boundaries. */
export function addMonths(ym: YearMonth, months: number): YearMonth {
	return fromOrdinal(ordinal(ym) + months);
}

/** Sort comparator: negative when `a` is earlier than `b`. */
export function compareYearMonth(a: YearMonth, b: YearMonth): number {
	return ordinal(a) - ordinal(b);
}

/** How many months the period covers, counting both endpoints. */
export function periodLength(period: Period): number {
	return ordinal(period.to) - ordinal(period.from) + 1;
}

/** Move a whole period by `months`, preserving its length. */
export function shiftPeriod(period: Period, months: number): Period {
	return { from: addMonths(period.from, months), to: addMonths(period.to, months) };
}

/** Every month in the period, ascending. */
export function periodMonths(period: Period): YearMonth[] {
	const length = periodLength(period);
	const start = ordinal(period.from);
	return Array.from({ length }, (_, i) => fromOrdinal(start + i));
}

/** The calendar year containing `today` — what `/spending` shows with no params. */
export function defaultPeriod(today: YearMonth): Period {
	return { from: { year: today.year, month: 1 }, to: { year: today.year, month: 12 } };
}

/** The canonical URL params for a period (`from=YYYY-MM&to=YYYY-MM`). */
export function periodParams(period: Period): URLSearchParams {
	const params = new URLSearchParams();
	params.set('from', formatYearMonth(period.from));
	params.set('to', formatYearMonth(period.to));
	return params;
}

/**
 * Resolve `?from=`/`?to=` (or the legacy `?year=`) into a period.
 *
 * Unparseable, half-missing or inverted input falls back to the default period —
 * quietly swapping an inverted range would turn nonsense into a confident-looking
 * answer. A range that parses but is too long instead **keeps its start and
 * clamps to 12 months**, so a hand-edited 18-month link still shows roughly what
 * was asked for rather than snapping back to "this year".
 *
 * Guaranteed idempotent: re-parsing `periodParams(result)` yields `result`, which
 * is what lets `load` redirect to the canonical URL without looping.
 */
export function parsePeriodParams(params: URLSearchParams, today: YearMonth): Period {
	const from = parseYearMonth(params.get('from'));
	const to = parseYearMonth(params.get('to'));

	if (from && to) {
		if (compareYearMonth(from, to) > 0) return defaultPeriod(today);
		return clampPeriod({ from, to });
	}

	// Legacy `?year=2025` — the report's original param. Kept so live and
	// bookmarked URLs survive the move to periods.
	const legacyYear = Number.parseInt(params.get('year') ?? '', 10);
	if (Number.isInteger(legacyYear) && legacyYear >= MIN_YEAR && legacyYear <= MAX_YEAR) {
		return { from: { year: legacyYear, month: 1 }, to: { year: legacyYear, month: 12 } };
	}

	return defaultPeriod(today);
}

/** Trim a period to at most `MAX_PERIOD_MONTHS`, keeping its start. */
function clampPeriod(period: Period): Period {
	if (periodLength(period) <= MAX_PERIOD_MONTHS) return period;
	return { from: period.from, to: addMonths(period.from, MAX_PERIOD_MONTHS - 1) };
}

/**
 * Column headings for a run of months, **year-qualified only when the run spans
 * two calendar years** (`Jul 25 … Jun 26`).
 *
 * This is not cosmetic: `buildSpendingChart` keys its bars by label, so two
 * unqualified "Jul"s from different years would collide on the band scale.
 */
export function monthColumnLabels(months: YearMonth[]): string[] {
	const spansYears = months.length > 0 && months[0].year !== months[months.length - 1].year;
	return months.map((m) =>
		spansYears
			? `${MONTH_LABELS[m.month - 1]} ${String(m.year).slice(-2)}`
			: MONTH_LABELS[m.month - 1]
	);
}

/**
 * Human-readable period, for headings and the comparison options:
 * a whole calendar year is just "2026", a part-year "Jan–Aug 2026", and a
 * cross-year period "Jul 2025 – Jun 2026".
 */
export function formatPeriod(period: Period): string {
	const fromLabel = MONTH_LABELS[period.from.month - 1];
	const toLabel = MONTH_LABELS[period.to.month - 1];

	if (period.from.year !== period.to.year) {
		return `${fromLabel} ${period.from.year} – ${toLabel} ${period.to.year}`;
	}
	if (period.from.month === 1 && period.to.month === 12) {
		return String(period.from.year);
	}
	if (period.from.month === period.to.month) {
		return `${fromLabel} ${period.from.year}`;
	}
	return `${fromLabel}–${toLabel} ${period.from.year}`;
}

