import { describe, it, expect } from 'vitest';
import {
	buildSpendingReport,
	hasReportData,
	visibleMonths,
	type SpendingExpense,
	type SpendingCategory
} from './spendingReport';
import type { Period, YearMonth } from './spendingPeriod';
import type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';

// --- fixtures ---------------------------------------------------------------

const importanceAreas: ImportanceArea[] = [
	{ id: 'imp-ess', name: 'Essential', sort_order: 1 },
	{ id: 'imp-pri', name: 'Priorities', sort_order: 2 },
	{ id: 'imp-oth', name: 'Other', sort_order: 3 }
];

const groups: CategoryGroup[] = [
	{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-ess' },
	{ id: 'grp-home', name: 'Home', importance_area_id: 'imp-ess' },
	{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-pri' },
	{ id: 'grp-disc', name: 'Discretionary', importance_area_id: 'imp-oth' }
];

const categories: SpendingCategory[] = [
	{ id: 'cat-groceries', name: 'Groceries', group_id: 'grp-everyday' },
	{ id: 'cat-clothes', name: 'Clothes', group_id: 'grp-everyday' },
	{ id: 'cat-utilities', name: 'Utilities', group_id: 'grp-home' },
	{ id: 'cat-allowance', name: 'Allowance', group_id: 'grp-kids' },
	{ id: 'cat-alcohol', name: 'Alcohol', group_id: 'grp-disc' },
	{ id: 'cat-orphan', name: 'Orphan', group_id: null } // no group → Uncategorized
];

const YEAR_2026: Period = { from: { year: 2026, month: 1 }, to: { year: 2026, month: 12 } };
// Most tests sit at the start of the period, so the visible columns run
// January → the last month that has data — the report's pre-period behaviour.
const JAN_2026: YearMonth = { year: 2026, month: 1 };

function expense(overrides: Partial<SpendingExpense>): SpendingExpense {
	return {
		total_amount: 100,
		transaction_date: '2026-01-15',
		category_id: 'cat-groceries',
		exchange_rate_to_cad: null,
		...overrides
	};
}

function report(expenses: SpendingExpense[], period: Period = YEAR_2026, today = JAN_2026) {
	return buildSpendingReport(expenses, categories, groups, importanceAreas, period, today);
}

/** Expected `months` array for a run of 2026 months. */
function months2026(from: number, to: number): YearMonth[] {
	return Array.from({ length: to - from + 1 }, (_, i) => ({ year: 2026, month: from + i }));
}

// Find a category row within an importance/group by name.
function findRow(
	r: ReturnType<typeof report>,
	importance: string,
	group: string,
	category: string
) {
	const imp = r.importances.find((i) => i.name === importance);
	const grp = imp?.groups.find((g) => g.name === group);
	return grp?.rows.find((row) => row.name === category);
}

// --- month columns ----------------------------------------------------------

describe('month columns', () => {
	it('runs from the period start → the last month that has any expense', () => {
		const r = report([
			expense({ transaction_date: '2026-01-10' }),
			expense({ transaction_date: '2026-06-20' })
		]);
		expect(r.months).toEqual(months2026(1, 6));
		expect(r.monthLabels).toEqual(['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun']);
	});

	it('ignores expenses outside the period when sizing the columns', () => {
		const r = report([
			expense({ transaction_date: '2026-03-01' }),
			expense({ transaction_date: '2025-12-01' }),
			expense({ transaction_date: '2027-01-01' })
		]);
		expect(r.months).toEqual(months2026(1, 3));
	});

	it('a null-amount receipt still extends the columns', () => {
		const r = report([expense({ transaction_date: '2026-05-01', total_amount: null })]);
		expect(r.months).toEqual(months2026(1, 5));
	});

	it('shows one empty column when the period has no expenses at all', () => {
		const r = report([expense({ transaction_date: '2025-05-01' })]);
		expect(r.months).toEqual(months2026(1, 1));
		expect(r.importances).toEqual([]);
		expect(r.uncategorized).toBeNull();
		expect(r.grandTotal.total.amount).toBe(0);
		expect(hasReportData(r)).toBe(false);
	});

	it('shows every elapsed month even when the later ones are empty', () => {
		// Today is August; only January has spend. The user asked for the calendar
		// year, so Feb–Aug are blank columns rather than missing ones.
		const r = report([expense({ transaction_date: '2026-01-10' })], YEAR_2026, {
			year: 2026,
			month: 8
		});
		expect(r.months).toEqual(months2026(1, 8));
	});

	it('drops months that are entirely in the future', () => {
		const r = report([expense({ transaction_date: '2026-01-10' })], YEAR_2026, {
			year: 2026,
			month: 8
		});
		expect(r.months.at(-1)).toEqual({ year: 2026, month: 8 });
	});

	it('keeps a future month that has data, so future-dated spend is never hidden', () => {
		// Receipts dated ahead of today are allowed (and flagged suspicious); the
		// Grand Total has to keep tying out to real spend.
		const r = report(
			[
				expense({ transaction_date: '2026-01-10', total_amount: 10 }),
				expense({ transaction_date: '2026-11-10', total_amount: 90 })
			],
			YEAR_2026,
			{ year: 2026, month: 8 }
		);
		expect(r.months).toEqual(months2026(1, 11));
		expect(r.grandTotal.total.amount).toBe(100);
	});

	it('renders a single column for a period entirely in the future', () => {
		const period: Period = { from: { year: 2027, month: 1 }, to: { year: 2027, month: 12 } };
		const r = report([], period, { year: 2026, month: 8 });
		expect(r.months).toEqual([{ year: 2027, month: 1 }]);
	});

	it('year-qualifies the labels of a cross-year period', () => {
		const period: Period = { from: { year: 2025, month: 11 }, to: { year: 2026, month: 2 } };
		const r = report([expense({ transaction_date: '2026-02-01' })], period, {
			year: 2026,
			month: 2
		});
		expect(r.monthLabels).toEqual(['Nov 25', 'Dec 25', 'Jan 26', 'Feb 26']);
	});

	it('buckets a cross-year period into the right columns', () => {
		const period: Period = { from: { year: 2025, month: 11 }, to: { year: 2026, month: 2 } };
		const r = report(
			[
				expense({ transaction_date: '2025-11-05', total_amount: 11 }),
				expense({ transaction_date: '2026-01-05', total_amount: 1 })
			],
			period,
			{ year: 2026, month: 2 }
		);
		const row = findRow(r, 'Essential', 'Everyday', 'Groceries')!;
		expect(row.cells.map((c) => c.amount)).toEqual([11, 0, 1, 0]);
		expect(row.total.amount).toBe(12);
	});

	it('carries the requested period through, even when columns are trimmed', () => {
		const r = report([expense({ transaction_date: '2026-01-10' })]);
		expect(r.period).toEqual(YEAR_2026);
	});
});

describe('visibleMonths', () => {
	it('stops at today when the period runs past it', () => {
		expect(visibleMonths(YEAR_2026, { year: 2026, month: 3 }, null)).toEqual(months2026(1, 3));
	});

	it('shows the whole period once it is entirely in the past', () => {
		expect(visibleMonths(YEAR_2026, { year: 2027, month: 6 }, null)).toEqual(months2026(1, 12));
	});

	it('extends past today to include a month that has data', () => {
		expect(
			visibleMonths(YEAR_2026, { year: 2026, month: 3 }, { year: 2026, month: 9 })
		).toEqual(months2026(1, 9));
	});

	it('never returns fewer than one month', () => {
		expect(visibleMonths(YEAR_2026, { year: 2020, month: 1 }, null)).toEqual(months2026(1, 1));
	});
});

// --- roll-up and subtotals --------------------------------------------------

describe('roll-up', () => {
	it('sums a category into the right month column and total', () => {
		const r = report([
			expense({ category_id: 'cat-groceries', transaction_date: '2026-01-05', total_amount: 40 }),
			expense({ category_id: 'cat-groceries', transaction_date: '2026-01-25', total_amount: 60 }),
			expense({ category_id: 'cat-groceries', transaction_date: '2026-02-10', total_amount: 30 })
		]);
		const row = findRow(r, 'Essential', 'Everyday', 'Groceries')!;
		expect(row.cells[0].amount).toBe(100); // Jan
		expect(row.cells[0].count).toBe(2);
		expect(row.cells[1].amount).toBe(30); // Feb
		expect(row.total.amount).toBe(130);
		expect(row.total.count).toBe(3);
	});

	it('group subtotal sums its categories', () => {
