import { buildSpendingReport, type SpendingExpense, type SpendingCategory } from './spendingReport';
import type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';
import type { Period, YearMonth } from './spendingPeriod';
import {
	comparisonLabel,
	comparisonModes,
	comparisonPeriod,
	hasPriorData,
	spendingChange,
	withPriorPeriod
} from './spendingComparison';

// --- fixtures (shared shape with spendingReport.spec) -----------------------

const importanceAreas: ImportanceArea[] = [
	{ id: 'imp-ess', name: 'Essential', sort_order: 1 },
	{ id: 'imp-pri', name: 'Priorities', sort_order: 2 },
	{ id: 'imp-oth', name: 'Other', sort_order: 3 }
];

const groups: CategoryGroup[] = [
	{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-ess' },
	{ id: 'grp-home', name: 'Home', importance_area_id: 'imp-ess' },
	{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-pri' }
];

const categories: SpendingCategory[] = [
	{ id: 'cat-groceries', name: 'Groceries', group_id: 'grp-everyday' },
	{ id: 'cat-clothes', name: 'Clothes', group_id: 'grp-everyday' },
	{ id: 'cat-utilities', name: 'Utilities', group_id: 'grp-home' },
	{ id: 'cat-allowance', name: 'Allowance', group_id: 'grp-kids' },
	{ id: 'cat-orphan', name: 'Orphan', group_id: null }
];

/** The whole calendar year `y`, the report's default period shape. */
function yearPeriod(y: number): Period {
	return { from: { year: y, month: 1 }, to: { year: y, month: 12 } };
}

function expense(overrides: Partial<SpendingExpense>): SpendingExpense {
	return {
		total_amount: 100,
		transaction_date: '2026-01-15',
		category_id: 'cat-groceries',
		exchange_rate_to_cad: null,
		...overrides
	};
}

function reportFor(expenses: SpendingExpense[], period: Period, today?: YearMonth) {
	return buildSpendingReport(
		expenses,
		categories,
		groups,
		importanceAreas,
		period,
		today ?? period.from
	);
}

/** Build current + prior-year reports and attach the comparison in one step. */
function compared(current: SpendingExpense[], prior: SpendingExpense[], year = 2026) {
	const currentReport = reportFor(current, yearPeriod(year));
	const priorReport = reportFor(prior, yearPeriod(year - 1), { year, month: 12 });
	return withPriorPeriod(currentReport, priorReport);
}

function findRow(
	r: ReturnType<typeof reportFor>,
	importance: string,
	group: string,
	category: string
) {
	const imp = r.importances.find((i) => i.name === importance);
	const grp = imp?.groups.find((g) => g.name === group);
	return grp?.rows.find((row) => row.name === category);
}

// --- which window a mode compares against -----------------------------------

describe('comparisonPeriod', () => {
	it('shifts back exactly a year for the prior-year mode, whatever the length', () => {
		const period: Period = { from: { year: 2026, month: 4 }, to: { year: 2026, month: 6 } };
		expect(comparisonPeriod(period, 'priorYear')).toEqual({
			from: { year: 2025, month: 4 },
			to: { year: 2025, month: 6 }
		});
	});

	it('shifts back by the period’s own length for the previous-period mode', () => {
		const period: Period = { from: { year: 2026, month: 4 }, to: { year: 2026, month: 6 } };
		expect(comparisonPeriod(period, 'priorPeriod')).toEqual({
			from: { year: 2026, month: 1 },
			to: { year: 2026, month: 3 }
		});
	});

	it('the two modes coincide for a 12-month period', () => {
		const period = yearPeriod(2026);
		expect(comparisonPeriod(period, 'priorPeriod')).toEqual(
			comparisonPeriod(period, 'priorYear')
		);
	});
});

describe('comparisonModes', () => {
	it('offers only the prior year for a 12-month period (the modes coincide)', () => {
		expect(comparisonModes(yearPeriod(2026))).toEqual(['priorYear']);
		expect(
			comparisonModes({ from: { year: 2025, month: 7 }, to: { year: 2026, month: 6 } })
		).toEqual(['priorYear']);
	});

	it('offers both for a shorter period', () => {
		expect(
			comparisonModes({ from: { year: 2026, month: 4 }, to: { year: 2026, month: 6 } })
		).toEqual(['priorYear', 'priorPeriod']);
	});
});

describe('comparisonLabel', () => {
	it('names the window a mode actually compares against', () => {
		const period: Period = { from: { year: 2026, month: 4 }, to: { year: 2026, month: 6 } };
		expect(comparisonLabel(period, 'priorYear')).toBe('Apr–Jun 2025');
		expect(comparisonLabel(period, 'priorPeriod')).toBe('Jan–Mar 2026');
	});
});

// --- withPriorPeriod --------------------------------------------------------

describe('withPriorPeriod', () => {
	it('attaches the prior-year total to a matching category, group, importance and grand total', () => {
		const r = compared(
			[expense({ transaction_date: '2026-01-10', total_amount: 100 })],
			[expense({ transaction_date: '2025-01-10', total_amount: 80 })]
		);
		const row = findRow(r, 'Essential', 'Everyday', 'Groceries')!;
		expect(row.priorTotal).toBe(80);
		const everyday = r.importances[0].groups.find((g) => g.name === 'Everyday')!;
		expect(everyday.subtotal.priorTotal).toBe(80);
		expect(r.importances[0].subtotal.priorTotal).toBe(80);
		expect(r.grandTotal.priorTotal).toBe(80);
	});

	it('truncates the comparison to the current report’s visible months (parity)', () => {
		// Current period has data only through March → window of 3 months.
		const current = [expense({ transaction_date: '2026-03-10', total_amount: 5 })];
		// Prior year spent 10 every month Jan–June; only Jan–Mar should count.
		const prior = [1, 2, 3, 4, 5, 6].map((m) =>
			expense({ transaction_date: `2025-0${m}-10`, total_amount: 10 })
		);
		const r = compared(current, prior);
		expect(r.months.length).toBe(3); // Jan–Mar
		expect(r.grandTotal.priorTotal).toBe(30); // 3 months × 10, not 60
	});

	it('counts prior months that fall before the window even when the prior year is shorter', () => {
		// Current runs Jan–June (window 6); prior only has Jan–Mar.
		const current = [expense({ transaction_date: '2026-06-10', total_amount: 5 })];
		const prior = [1, 2, 3].map((m) =>
			expense({ transaction_date: `2025-0${m}-10`, total_amount: 10 })
		);
		const r = compared(current, prior);
		expect(r.months.length).toBe(6);
		expect(r.grandTotal.priorTotal).toBe(30); // the 3 months it had; the rest are $0
	});

	it('gives a category with no prior-year spend a prior of 0 (it is "new")', () => {
		const r = compared(
			[expense({ category_id: 'cat-clothes', total_amount: 50 })],
			[expense({ category_id: 'cat-groceries', transaction_date: '2025-01-10', total_amount: 40 })]
		);
		const clothes = findRow(r, 'Essential', 'Everyday', 'Clothes')!;
		expect(clothes.priorTotal).toBe(0);
	});

	it('matches uncategorized rows by id and the "(No category)" row by name', () => {
		const r = compared(
			[
				expense({ category_id: 'cat-orphan', total_amount: 50 }),
				expense({ category_id: null, total_amount: 20 })
			],
			[
				expense({ category_id: 'cat-orphan', transaction_date: '2025-01-10', total_amount: 30 }),
				expense({ category_id: null, transaction_date: '2025-01-10', total_amount: 15 })
			]
		);
		const orphan = r.uncategorized!.rows.find((row) => row.name === 'Orphan')!;
		const noCat = r.uncategorized!.rows.find((row) => row.name === '(No category)')!;
		expect(orphan.priorTotal).toBe(30);
		expect(noCat.priorTotal).toBe(15);
		expect(r.uncategorized!.subtotal.priorTotal).toBe(45);
	});

	it('includes uncategorized prior spend in the grand-total comparison', () => {
		const r = compared(
			[expense({ category_id: 'cat-groceries', total_amount: 100 })],
			[
				expense({ category_id: 'cat-groceries', transaction_date: '2025-01-10', total_amount: 40 }),
				expense({ category_id: 'cat-orphan', transaction_date: '2025-01-10', total_amount: 60 })
			]
		);
		expect(r.grandTotal.priorTotal).toBe(100);
	});

	it('compares an empty current period over its one visible month', () => {
		const r = compared([], [expense({ transaction_date: '2025-01-10', total_amount: 40 })]);
		expect(r.months.length).toBe(1);
		expect(r.grandTotal.priorTotal).toBe(40);
	});

	it('leaves the base report untouched, so switching the comparison off restores it', () => {
		const base = reportFor([expense({ total_amount: 100 })], yearPeriod(2026));
		const prior = reportFor(
			[expense({ transaction_date: '2025-01-10', total_amount: 80 })],
			yearPeriod(2025),
			{ year: 2026, month: 12 }
		);
		const annotated = withPriorPeriod(base, prior);

		expect(annotated.grandTotal.priorTotal).toBe(80);
		expect(base.grandTotal.priorTotal).toBeUndefined();
		expect(base.importances[0].groups[0].rows[0].priorTotal).toBeUndefined();
	});

	it('re-annotating from the base swaps the comparison window cleanly', () => {
		const period: Period = { from: { year: 2026, month: 4 }, to: { year: 2026, month: 6 } };
		const today: YearMonth = { year: 2026, month: 6 };
		const base = reportFor([expense({ transaction_date: '2026-04-10', total_amount: 100 })], period);
		const lastYear = reportFor(
			[expense({ transaction_date: '2025-04-10', total_amount: 10 })],
			comparisonPeriod(period, 'priorYear'),
			today
		);
		const lastQuarter = reportFor(
			[expense({ transaction_date: '2026-01-10', total_amount: 20 })],
			comparisonPeriod(period, 'priorPeriod'),
			today
		);

		expect(withPriorPeriod(base, lastYear).grandTotal.priorTotal).toBe(10);
		expect(withPriorPeriod(base, lastQuarter).grandTotal.priorTotal).toBe(20);
	});
});

