/**
 * Spending Report → Expenses drill-down (pure)
 *
 * Turns a clicked report cell into the URL query the Expenses page already
 * understands, so a number in the roll-up jumps to exactly the Expenses that
 * produced it. No I/O — a plain function, unit-tested like `spendingReport`.
 *
 * Design: docs/plans/2026-07-09-spending-report-design.md ("drill from a table
 * cell into the Expenses view", "Period selection").
 *
 * The Expenses page reads (see src/routes/expenses/+page.svelte):
 * - `dateFrom` / `dateTo` — inclusive `YYYY-MM-DD` bounds (via readDateFilter).
 * - `category` — comma-separated category ids (OR filter).
 * - `filter=uncategorized` — show only expenses with no category (takes
 *   precedence over `category`, so the two are never set together).
 *
 * It also carries `periodFrom` / `periodTo`, which the Expenses page ignores:
 * they exist so the layout's Spending tab can bring the reader back to the
 * period they were looking at. The names are deliberately distinct from
 * `dateFrom` / `dateTo` — on the same URL the two pairs mean different things.
 */

import type { SpendingCategory } from './spendingReport';
import { formatYearMonth, type Period, type YearMonth } from './spendingPeriod';
import type { CategoryGroup } from '$lib/types/Hierarchy';

/** What a clicked cell rolls up — the row/section identity. */
export type DrilldownScope =
	| { kind: 'category'; categoryId: string }
	| { kind: 'group'; groupId: string }
	| { kind: 'importance'; importanceId: string }
	| { kind: 'uncategorized' }
	| { kind: 'grandTotal' };

/** Which column was clicked — a single month or the period's Total roll-up. */
export type DrilldownColumn = { kind: 'month'; month: YearMonth } | { kind: 'total' };

/** Everything a cell needs beyond its own identity to become a URL. */
export interface DrilldownContext {
	/** The report's visible months, ascending — these bound the Total column. */
	months: YearMonth[];
	/** The selected period, echoed back so the reader can return to it. */
	period: Period;
	/** Family categories (to expand a group/importance to its ids). */
	categories: SpendingCategory[];
	/** Family groupings (to expand an importance to its groups). */
	groups: CategoryGroup[];
}

const pad = (n: number): string => String(n).padStart(2, '0');

/** First day of a month, `YYYY-MM-DD`. */
function firstDay(ym: YearMonth): string {
	return `${ym.year}-${pad(ym.month)}-01`;
}

/** Last day of a month, `YYYY-MM-DD`. Numeric Date args are timezone-safe here. */
function lastDay(ym: YearMonth): string {
	return `${ym.year}-${pad(ym.month)}-${pad(new Date(ym.year, ym.month, 0).getDate())}`;
}

/**
 * Inclusive `YYYY-MM-DD` bounds for the clicked column.
 *
 * The Total column spans the **visible** months rather than the whole selected
 * period, so it matches the number it was clicked on: a period running to
 * December but only shown through August must not pull in expenses the column
 * never summed.
 */
function dateBounds(
	column: DrilldownColumn,
