/**
 * Build the chart model for the current expand state.
 *
 * @param report         The spending report for the selected year.
 * @param expandedGroups Grouping names currently expanded to their Categories.
 */
export function buildSpendingChart(
	report: SpendingReport,
=== chart spec ===
import { describe, it, expect } from 'vitest';
import { buildSpendingReport, type SpendingExpense, type SpendingCategory } from './spendingReport';
import type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';
import { buildSpendingChart } from './spendingChart';
import { withPriorPeriod } from './spendingComparison';

// Reuse the report fixtures so the chart is tested against real report output.
const importanceAreas: ImportanceArea[] = [
	{ id: 'imp-ess', name: 'Essential', sort_order: 1 },
	{ id: 'imp-pri', name: 'Priorities', sort_order: 2 },
	{ id: 'imp-oth', name: 'Other', sort_order: 3 }
];

const groups: CategoryGroup[] = [
	{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-ess' },
	{ id: 'grp-home', name: 'Home', importance_area_id: 'imp-ess' },
	{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-pri' }
];

const categories: SpendingCategory[] = [
	{ id: 'cat-groceries', name: 'Groceries', group_id: 'grp-everyday' },
	{ id: 'cat-clothes', name: 'Clothes', group_id: 'grp-everyday' },
	{ id: 'cat-utilities', name: 'Utilities', group_id: 'grp-home' },
	{ id: 'cat-allowance', name: 'Allowance', group_id: 'grp-kids' },
	{ id: 'cat-orphan', name: 'Orphan', group_id: null }
];

function expense(overrides: Partial<SpendingExpense>): SpendingExpense {
	return {
		total_amount: 100,
		transaction_date: '2026-01-15',
		category_id: 'cat-groceries',
		exchange_rate_to_cad: null,
		...overrides
	};
}

function chart(expenses: SpendingExpense[], expanded: string[] = []) {
	const report = buildSpendingReport(expenses, categories, groups, importanceAreas, 2026);
	return buildSpendingChart(report, new Set(expanded));
}

const mixed = [
	expense({ category_id: 'cat-groceries', total_amount: 40 }), // Essential/Everyday
	expense({ category_id: 'cat-clothes', total_amount: 25 }), // Essential/Everyday
	expense({ category_id: 'cat-utilities', total_amount: 200 }), // Essential/Home
	expense({ category_id: 'cat-allowance', total_amount: 10 }), // Priorities/Kids
	expense({ category_id: 'cat-orphan', total_amount: 60 }) // Uncategorized
];

describe('collapsed (nothing expanded)', () => {
	it('emits one group bar per grouping, ordered by importance then name', () => {
		const model = chart(mixed);
		expect(model.bars.map((b) => b.name)).toEqual(['Everyday', 'Home', 'Kids', 'Uncategorized']);
		expect(model.bars.every((b) => b.kind === 'group')).toBe(true);
		expect(model.bars.map((b) => b.importance)).toEqual([
			'Essential',
			'Essential',
			'Priorities',
			''
		]);
	});

	it('keys each group total by month label', () => {
		const model = chart([
			expense({ category_id: 'cat-groceries', transaction_date: '2026-01-05', total_amount: 40 }),
			expense({ category_id: 'cat-clothes', transaction_date: '2026-03-05', total_amount: 25 })
		]);
		const everyday = model.bars.find((b) => b.name === 'Everyday')!;
		expect(everyday.monthly).toEqual({ Jan: 40, Feb: 0, Mar: 25 });
		expect(everyday.total).toBe(65);
	});
});

describe('expand in place', () => {
	it('replaces one grouping with its category bars, siblings unchanged', () => {
		const model = chart(mixed, ['Everyday']);
		expect(model.bars.map((b) => b.name)).toEqual([
			'Clothes', // Everyday expanded → its categories, in place
			'Groceries',
			'Home', // siblings stay as group bars
			'Kids',
			'Uncategorized'
		]);
		const cats = model.bars.filter((b) => b.groupName === 'Everyday');
		expect(cats.every((b) => b.kind === 'category')).toBe(true);
