import { describe, it, expect, beforeEach, vi } from 'vitest';
import type { SupabaseClient } from '@supabase/supabase-js';
import { ExpenseService, type Expense } from './ExpenseService';
import { makeExpense } from '$lib/tests/builders/rowBuilders';
import { createMockSupabaseClient, getMockQuery, setFromResult } from './expenseServiceTestHelpers';

describe('ExpenseService - pagination past the 1000-row cap', () => {
	/** A minimal receipts-query builder whose `.range()` returns the next queued page. */
	function clientReturningPages(pages: unknown[][]): SupabaseClient {
		let call = 0;
		const builder = {
			select: () => builder,
			gte: () => builder,
			lte: () => builder,
			ilike: () => builder,
			order: () => builder,
			range: () => Promise.resolve({ data: pages[call++] ?? [], error: null })
		};
		return { from: () => builder } as unknown as SupabaseClient;
	}

	const makeRow = (i: number) => ({
		id: `r${i}`,
		merchant_name: 'M',
		total_amount: 1,
		transaction_date: '2025-01-01'
	});

	it('fetches every page when the result exceeds one page, then stops on a short page', async () => {
		const fullPage = Array.from({ length: 1000 }, (_, i) => makeRow(i));
		const partialPage = [makeRow(1000), makeRow(1001)];
		const service = new ExpenseService(clientReturningPages([fullPage, partialPage]));

		const expenses = await service.getExpenses('u');

		// 1000 (page 1) + 2 (page 2) — the short second page ends paging.
		expect(expenses).toHaveLength(1002);
	});

	it('does not request a second page when the first page is short', async () => {
		const pages = [[makeRow(0)], [makeRow(999)]]; // second page must never be read
		const service = new ExpenseService(clientReturningPages(pages));

		const expenses = await service.getExpenses('u');

		expect(expenses).toHaveLength(1);
	});
});

