import { ExpenseService } from './ExpenseService';

/**
 * `getExpenseDateBounds` feeds the Spending report's period picker, whose year
 * options span the family's real data. It asks for one row from each end of the
 * `transaction_date` order, so these tests assert on the sort direction rather
 * than on any client-side scan.
 */
function clientReturning(rowsByAscending: { asc: unknown[]; desc: unknown[] }) {
	const orders: { ascending: boolean }[] = [];
	const builder = {
		select: () => builder,
		order: (_column: string, opts: { ascending: boolean }) => {
			orders.push(opts);
			return {
				limit: () =>
					Promise.resolve({
						data: opts.ascending ? rowsByAscending.asc : rowsByAscending.desc,
						error: null
					})
			};
		}
	};
	return { client: { from: () => builder } as unknown as SupabaseClient, orders };
}

describe('ExpenseService.getExpenseDateBounds', () => {
	it('reads the first and last transaction_date from opposite sort orders', async () => {
		const { client, orders } = clientReturning({
			asc: [{ transaction_date: '2019-03-04' }],
			desc: [{ transaction_date: '2026-08-01' }]
		});

		const bounds = await new ExpenseService(client).getExpenseDateBounds();

		expect(bounds).toEqual({ earliest: '2019-03-04', latest: '2026-08-01' });
		expect(orders.map((o) => o.ascending).sort()).toEqual([false, true]);
	});

	it('returns nulls when the family has no receipts', async () => {
		const { client } = clientReturning({ asc: [], desc: [] });

		expect(await new ExpenseService(client).getExpenseDateBounds()).toEqual({
			earliest: null,
			latest: null
		});
	});

	it('surfaces a query error rather than pretending the family has no data', async () => {
		const builder = {
			select: () => builder,
			order: () => ({ limit: () => Promise.resolve({ data: null, error: { message: 'nope' } }) })
		};
		const client = { from: () => builder } as unknown as SupabaseClient;

		await expect(new ExpenseService(client).getExpenseDateBounds()).rejects.toThrow('nope');
	});
});

