import { redirect } from '@sveltejs/kit';
import type { PageLoad } from './$types';
import { parsePeriodParams, periodParams } from '$lib/utils/spendingPeriod';

/**
 * The Spending report's selected period lives in the URL
 * (`/spending?from=2025-07&to=2026-06`).
 *
 * Reading it in `load` (rather than a client-side `$derived` off the page store)
 * is what makes it reliable: SvelteKit re-runs `load` with the correct `url` on
 * every navigation — the period picker (`goto`), a browser Back from a
 * drill-down, and a full refresh — so `data.period` is always in lock-step with
 * the URL. Earlier client-only attempts (read-once in onMount, then `$derived`
 * off the `$app/stores` / `$app/state` page) went stale on Back.
 *
 * Anything that isn't already the canonical spelling of the resolved period —
 * no params at all, the legacy `?year=`, an over-long range that got clamped —
 * redirects to the canonical URL, so the address bar and the picker always agree.
 * `parsePeriodParams` is idempotent over `periodParams`, which is what stops that
 * redirect from looping.
 */
export const load: PageLoad = ({ url }) => {
	const now = new Date();
	const period = parsePeriodParams(url.searchParams, {
		year: now.getFullYear(),
		month: now.getMonth() + 1
	});

	const canonical = periodParams(period);
	if (
		url.searchParams.get('from') !== canonical.get('from') ||
		url.searchParams.get('to') !== canonical.get('to')
	) {
		redirect(307, `/spending?${canonical}`);
	}

	return { period };
};

