// The Spending report's period, forwarded onto its own tab link the same way.
// On /spending it is `from`/`to`; on a page reached by drilling down from the
// report it arrives as `periodFrom`/`periodTo` (distinct names, because on that
// URL `dateFrom`/`dateTo` mean the clicked cell, not the report's period).
// Without this, clicking Spending from a drill-down would reset to the default
// period. See docs/plans/2026-07-09-spending-report-design.md.
let spendingQuery = $derived.by(() => {
	const params = $page.url.searchParams;
	const from = params.get('from') ?? params.get('periodFrom');
	const to = params.get('to') ?? params.get('periodTo');

	const newParams = new SvelteURLSearchParams();
	if (from && to) {
		newParams.set('from', from);
		newParams.set('to', to);
	}

	return newParams.toString();
});

