1	/**
2	 * Spending Report → Expenses drill-down (pure)
3	 *
4	 * Turns a clicked report cell into the URL query the Expenses page already
5	 * understands, so a number in the roll-up jumps to exactly the Expenses that
6	 * produced it. No I/O — a plain function, unit-tested like `spendingReport`.
7	 *
8	 * Design: docs/plans/2026-07-09-spending-report-design.md ("drill from a table
9	 * cell into the Expenses view", "Period selection").
10	 *
11	 * The Expenses page reads (see src/routes/expenses/+page.svelte):
12	 * - `dateFrom` / `dateTo` — inclusive `YYYY-MM-DD` bounds (via readDateFilter).
13	 * - `category` — comma-separated category ids (OR filter).
14	 * - `filter=uncategorized` — show only expenses with no category (takes
15	 *   precedence over `category`, so the two are never set together).
16	 *
17	 * It also carries `periodFrom` / `periodTo`, which the Expenses page ignores:
18	 * they exist so the layout's Spending tab can bring the reader back to the
19	 * period they were looking at. The names are deliberately distinct from
20	 * `dateFrom` / `dateTo` — on the same URL the two pairs mean different things.
21	 */
22	
23	import type { SpendingCategory } from './spendingReport';
24	import { formatYearMonth, type Period, type YearMonth } from './spendingPeriod';
25	import type { CategoryGroup } from '$lib/types/Hierarchy';
26	
27	/** What a clicked cell rolls up — the row/section identity. */
28	export type DrilldownScope =
29		| { kind: 'category'; categoryId: string }
30		| { kind: 'group'; groupId: string }
31		| { kind: 'importance'; importanceId: string }
32		| { kind: 'uncategorized' }
33		| { kind: 'grandTotal' };
34	
35	/** Which column was clicked — a single month or the period's Total roll-up. */
36	export type DrilldownColumn = { kind: 'month'; month: YearMonth } | { kind: 'total' };
37	
38	/** Everything a cell needs beyond its own identity to become a URL. */
39	export interface DrilldownContext {
40		/** The report's visible months, ascending — these bound the Total column. */
41		months: YearMonth[];
42		/** The selected period, echoed back so the reader can return to it. */
43		period: Period;
44		/** Family categories (to expand a group/importance to its ids). */
45		categories: SpendingCategory[];
46		/** Family groupings (to expand an importance to its groups). */
47		groups: CategoryGroup[];
48	}
49	
50	const pad = (n: number): string => String(n).padStart(2, '0');
51	
52	/** First day of a month, `YYYY-MM-DD`. */
53	function firstDay(ym: YearMonth): string {
54		return `${ym.year}-${pad(ym.month)}-01`;
55	}
56	
57	/** Last day of a month, `YYYY-MM-DD`. Numeric Date args are timezone-safe here. */
58	function lastDay(ym: YearMonth): string {
59		return `${ym.year}-${pad(ym.month)}-${pad(new Date(ym.year, ym.month, 0).getDate())}`;
60	}
61	
62	/**
63	 * Inclusive `YYYY-MM-DD` bounds for the clicked column.
64	 *
65	 * The Total column spans the **visible** months rather than the whole selected
66	 * period, so it matches the number it was clicked on: a period running to
67	 * December but only shown through August must not pull in expenses the column
68	 * never summed.
69	 */
70	function dateBounds(column: DrilldownColumn, months: YearMonth[]): { from: string; to: string } {
71		if (column.kind === 'month') {
72			return { from: firstDay(column.month), to: lastDay(column.month) };
73		}
74		return { from: firstDay(months[0]), to: lastDay(months[months.length - 1]) };
75	}
76	
77	/**
78	 * Build the `/expenses?…` query params for a clicked Spending Report cell.
79	 *
80	 * @param scope   What the cell rolls up (category / group / importance / …).
81	 * @param column  The clicked month, or the Total column.
82	 * @param context The report's months and period plus the family hierarchy.
83	 */
84	export function buildSpendingDrilldownParams(
85		scope: DrilldownScope,
86		column: DrilldownColumn,
87		context: DrilldownContext
88	): URLSearchParams {
89		const params = new URLSearchParams();
90		const { from, to } = dateBounds(column, context.months);
91		params.set('dateFrom', from);
92		params.set('dateTo', to);
93	
94		if (scope.kind === 'uncategorized') {
95			params.set('filter', 'uncategorized');
96		} else {
97			const categoryIds = scopeCategoryIds(scope, context.categories, context.groups);
98			if (categoryIds && categoryIds.length > 0) {
99				params.set('category', categoryIds.join(','));
100			}
101		}
102	
103		params.set('periodFrom', formatYearMonth(context.period.from));
104		params.set('periodTo', formatYearMonth(context.period.to));
105	
106		return params;
107	}
108	
109	/**
110	 * The category ids a scope rolls up, or null when the scope carries no category
111	 * filter (grand total → all expenses; uncategorized → the `filter` param instead).
112	 */
113	function scopeCategoryIds(
114		scope: DrilldownScope,
115		categories: SpendingCategory[],
116		groups: CategoryGroup[]
117	): string[] | null {
118		switch (scope.kind) {
119			case 'category':
120				return [scope.categoryId];
121			case 'group':
122				return categories.filter((c) => c.group_id === scope.groupId).map((c) => c.id);
123			case 'importance': {
124				const groupIds = new Set(
125					groups.filter((g) => g.importance_area_id === scope.importanceId).map((g) => g.id)
126				);
127				return categories
128					.filter((c) => c.group_id != null && groupIds.has(c.group_id))
129					.map((c) => c.id);
130			}
131			default:
132				return null;
133		}
134	}

