import { describe, it, expect, vi } from 'vitest';
import { render } from 'vitest-browser-svelte';
import PeriodPicker from './PeriodPicker.svelte';
import type { Period } from '$lib/utils/spendingPeriod';

/**
 * Render tests for the Spending report's period picker. The period arithmetic is
 * unit-tested in spendingPeriod.spec.ts; these prove the two constraints that
 * only exist in the UI — the To options never leave the 12-month cap, and moving
 * From drags To along — plus the arrows shifting by the period's own length.
 */

const YEAR_2026: Period = { from: { year: 2026, month: 1 }, to: { year: 2026, month: 12 } };
const YEARS = [2024, 2025, 2026, 2027];

function setup(period: Period = YEAR_2026) {
	const onChange = vi.fn();
	const screen = render(PeriodPicker, { period, years: YEARS, onChange });
	return { screen, onChange };
}

/** The `<option>` values of a select, as they'd be picked. */
function optionValues(select: Element): string[] {
	return [...select.querySelectorAll('option')].map((o) => (o as HTMLOptionElement).value);
}

function selectByLabel(screen: ReturnType<typeof render>, label: string): HTMLSelectElement {
	return screen.baseElement.querySelector(`select[aria-label="${label}"]`) as HTMLSelectElement;
}

async function choose(select: HTMLSelectElement, value: string) {
	select.value = value;
	select.dispatchEvent(new Event('change', { bubbles: true }));
}

describe('PeriodPicker', () => {
	it('shows the current period across its four selects', async () => {
		const { screen } = setup({ from: { year: 2025, month: 7 }, to: { year: 2026, month: 6 } });

		expect(selectByLabel(screen, 'Period start month').value).toBe('7');
		expect(selectByLabel(screen, 'Period start year').value).toBe('2025');
		expect(selectByLabel(screen, 'Period end month').value).toBe('6');
		expect(selectByLabel(screen, 'Period end year').value).toBe('2026');
	});

	it('offers only the months the 12-month cap allows for the end year', async () => {
		// From Jul 2025, the cap runs to Jun 2026 — so 2026 offers Jan…Jun only.
		const { screen } = setup({ from: { year: 2025, month: 7 }, to: { year: 2026, month: 6 } });

		expect(optionValues(selectByLabel(screen, 'Period end month'))).toEqual([
			'1',
			'2',
			'3',
			'4',
			'5',
			'6'
		]);
		expect(optionValues(selectByLabel(screen, 'Period end year'))).toEqual(['2025', '2026']);
	});

	it('offers only the start year when the period cannot reach into the next one', async () => {
		const { screen } = setup(YEAR_2026);

		expect(optionValues(selectByLabel(screen, 'Period end year'))).toEqual(['2026']);
		expect(optionValues(selectByLabel(screen, 'Period end month'))).toHaveLength(12);
	});

	it('drags the end along when the start moves, preserving the span', async () => {
		const { screen, onChange } = setup({
			from: { year: 2026, month: 1 },
			to: { year: 2026, month: 3 }
		});

		await choose(selectByLabel(screen, 'Period start month'), '6');

