		expect(onChange).toHaveBeenCalledWith({
			from: { year: 2026, month: 6 },
			to: { year: 2026, month: 8 }
		});
	});

	it('keeps the span when the start year moves', async () => {
		const { screen, onChange } = setup(YEAR_2026);

		await choose(selectByLabel(screen, 'Period start year'), '2024');

		expect(onChange).toHaveBeenCalledWith({
			from: { year: 2024, month: 1 },
			to: { year: 2024, month: 12 }
		});
	});

	it('moves only the end when the end is picked', async () => {
		const { screen, onChange } = setup(YEAR_2026);

		await choose(selectByLabel(screen, 'Period end month'), '6');

		expect(onChange).toHaveBeenCalledWith({
			from: { year: 2026, month: 1 },
			to: { year: 2026, month: 6 }
		});
	});

	it('lands on the nearest allowed month when the end year changes out from under it', async () => {
		// From Jul 2025 with the end at Dec 2025; switching the end year to 2026
		// can't keep December — the cap stops at June.
		const { screen, onChange } = setup({
			from: { year: 2025, month: 7 },
			to: { year: 2025, month: 12 }
		});

		await choose(selectByLabel(screen, 'Period end year'), '2026');

		expect(onChange).toHaveBeenCalledWith({
			from: { year: 2025, month: 7 },
			to: { year: 2026, month: 6 }
		});
	});

	it('steps the whole window back by its own length', async () => {
		const { screen, onChange } = setup({
			from: { year: 2026, month: 4 },
			to: { year: 2026, month: 6 }
		});

		await screen.getByRole('button', { name: 'Previous period' }).click();

		expect(onChange).toHaveBeenCalledWith({
			from: { year: 2026, month: 1 },
			to: { year: 2026, month: 3 }
		});
	});

	it('steps a 12-month window a whole year, exactly like the year arrows it replaced', async () => {
		const { screen, onChange } = setup(YEAR_2026);

		await screen.getByRole('button', { name: 'Next period' }).click();

