import { describe, it, expect } from 'vitest';
import {
	buildSpendingDrilldownParams,
	type DrilldownColumn,
	type DrilldownContext,
	type DrilldownScope
} from './spendingDrilldown';
import type { SpendingCategory } from './spendingReport';
import { periodMonths, type Period } from './spendingPeriod';
import type { CategoryGroup } from '$lib/types/Hierarchy';

// A small two-importance hierarchy shared across the drilldown tests.
//   Essential → Everyday → [Groceries, Dining]
//   Priorities → Kids → [Daycare]
const categories: SpendingCategory[] = [
	{ id: 'cat-groceries', name: 'Groceries', group_id: 'grp-everyday' },
	{ id: 'cat-dining', name: 'Dining', group_id: 'grp-everyday' },
	{ id: 'cat-daycare', name: 'Daycare', group_id: 'grp-kids' },
	{ id: 'cat-orphan', name: 'Orphan', group_id: null }
];

const groups: CategoryGroup[] = [
	{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-essential' },
	{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-priorities' }
];

const YEAR_2026: Period = { from: { year: 2026, month: 1 }, to: { year: 2026, month: 12 } };

/** Context for a period whose columns are all visible. */
function context(period: Period = YEAR_2026, overrides: Partial<DrilldownContext> = {}) {
	return {
		months: periodMonths(period),
		period,
		categories,
		groups,
		...overrides
	};
}

const month = (year: number, m: number): DrilldownColumn => ({
	kind: 'month',
	month: { year, month: m }
});
const TOTAL: DrilldownColumn = { kind: 'total' };

function params(scope: DrilldownScope, column: DrilldownColumn, ctx = context()) {
	return buildSpendingDrilldownParams(scope, column, ctx);
}

describe('buildSpendingDrilldownParams', () => {
	it('links a category × month cell to that category and that month', () => {
		const p = params({ kind: 'category', categoryId: 'cat-groceries' }, month(2026, 3));

		expect(p.get('category')).toBe('cat-groceries');
		expect(p.get('dateFrom')).toBe('2026-03-01');
		expect(p.get('dateTo')).toBe('2026-03-31');
		expect(p.get('filter')).toBeNull();
	});

	it('links a category × Total cell to the whole visible period', () => {
		const p = params({ kind: 'category', categoryId: 'cat-groceries' }, TOTAL);

		expect(p.get('category')).toBe('cat-groceries');
		expect(p.get('dateFrom')).toBe('2026-01-01');
		expect(p.get('dateTo')).toBe('2026-12-31');
	});

	it('bounds the Total column by the visible months, not the whole period', () => {
		// The period runs to December but only Jan–Aug are shown; the Total column
		// sums those, so its link must not reach past August.
		const visible = periodMonths({ from: { year: 2026, month: 1 }, to: { year: 2026, month: 8 } });
		const p = params({ kind: 'grandTotal' }, TOTAL, context(YEAR_2026, { months: visible }));

		expect(p.get('dateFrom')).toBe('2026-01-01');
		expect(p.get('dateTo')).toBe('2026-08-31');
	});

	it('uses the correct last day for a short month (February, non-leap)', () => {
		const period: Period = { from: { year: 2027, month: 1 }, to: { year: 2027, month: 3 } };
		const p = params(
			{ kind: 'category', categoryId: 'cat-groceries' },
			month(2027, 2),
			context(period)
		);

		expect(p.get('dateFrom')).toBe('2027-02-01');
		expect(p.get('dateTo')).toBe('2027-02-28');
	});

	it('resolves a month by its own year, so a cross-year period lands correctly', () => {
		const period: Period = { from: { year: 2025, month: 11 }, to: { year: 2026, month: 2 } };
		const p = params({ kind: 'grandTotal' }, month(2025, 11), context(period));

		expect(p.get('dateFrom')).toBe('2025-11-01');
		expect(p.get('dateTo')).toBe('2025-11-30');
	});

	it('spans both years for the Total column of a cross-year period', () => {
		const period: Period = { from: { year: 2025, month: 11 }, to: { year: 2026, month: 2 } };
		const p = params({ kind: 'grandTotal' }, TOTAL, context(period));

		expect(p.get('dateFrom')).toBe('2025-11-01');
		expect(p.get('dateTo')).toBe('2026-02-28');
	});

	it('expands a Grouping subtotal to every category id in that group', () => {
		const p = params({ kind: 'group', groupId: 'grp-everyday' }, month(2026, 3));

		expect(p.get('category')?.split(',').sort()).toEqual(['cat-dining', 'cat-groceries']);
		expect(p.get('dateFrom')).toBe('2026-03-01');
		expect(p.get('dateTo')).toBe('2026-03-31');
	});

	it('expands an Importance subtotal to every category across its groups', () => {
		// Add a second Essential group so the importance spans more than one group.
		const withSecondGroup: CategoryGroup[] = [
			...groups,
			{ id: 'grp-home', name: 'Home', importance_area_id: 'imp-essential' }
		];
		const withHomeCat: SpendingCategory[] = [
			...categories,
			{ id: 'cat-rent', name: 'Rent', group_id: 'grp-home' }
		];

		const p = params(
			{ kind: 'importance', importanceId: 'imp-essential' },
			TOTAL,
			context(YEAR_2026, { categories: withHomeCat, groups: withSecondGroup })
		);

		// Everyday (Groceries, Dining) + Home (Rent) — but NOT Priorities' Daycare.
		expect(p.get('category')?.split(',').sort()).toEqual([
			'cat-dining',
			'cat-groceries',
			'cat-rent'
		]);
	});

	it('links an Uncategorized cell via filter=uncategorized, not a category list', () => {
		const p = params({ kind: 'uncategorized' }, month(2026, 5));

		expect(p.get('filter')).toBe('uncategorized');
		expect(p.get('category')).toBeNull();
		expect(p.get('dateFrom')).toBe('2026-05-01');
		expect(p.get('dateTo')).toBe('2026-05-31');
	});

	it('links the Grand Total to the date range alone (all expenses, incl. Uncategorized)', () => {
		const p = params({ kind: 'grandTotal' }, TOTAL);

		expect(p.get('category')).toBeNull();
		expect(p.get('filter')).toBeNull();
		expect(p.get('dateFrom')).toBe('2026-01-01');
		expect(p.get('dateTo')).toBe('2026-12-31');
	});

	it('omits the category param entirely when a group has no categories', () => {
		const p = params({ kind: 'group', groupId: 'grp-empty' }, month(2026, 1));

		// An empty `category=` would filter Expenses to a bogus id → show nothing.
		expect(p.has('category')).toBe(false);
		expect(p.get('dateFrom')).toBe('2026-01-01');
	});

	// --- the period round-trip ------------------------------------------------

	it('echoes the selected period so the Spending tab can return to it', () => {
		const period: Period = { from: { year: 2025, month: 7 }, to: { year: 2026, month: 6 } };
		const p = params({ kind: 'grandTotal' }, month(2025, 8), context(period));

		expect(p.get('periodFrom')).toBe('2025-07');
		expect(p.get('periodTo')).toBe('2026-06');
	});

	it('carries the period on an Uncategorized cell too', () => {
		const p = params({ kind: 'uncategorized' }, TOTAL);

		expect(p.get('filter')).toBe('uncategorized');
		expect(p.get('periodFrom')).toBe('2026-01');
		expect(p.get('periodTo')).toBe('2026-12');
	});

	it('echoes the period asked for, not the trimmed visible range', () => {
		// The columns stop in August, but returning should restore the whole year.
		const visible = periodMonths({ from: { year: 2026, month: 1 }, to: { year: 2026, month: 8 } });
		const p = params({ kind: 'grandTotal' }, TOTAL, context(YEAR_2026, { months: visible }));

		expect(p.get('periodTo')).toBe('2026-12');
	});
});
